/* ── Full-bleed colour bands on /evidence and /read-2-succeed ──
   These sections sit inside .container (max-width 1240px), so their
   backgrounds were rendering as inset blocks. Escape the container,
   then re-centre the content at the same measure. */
.ev-counts-section,
.ev-gap-section,
.ev-gov-section,
.r2s-strip,
.r2s-schools,
.r2s-measure {
  width: 100vw;
  max-width: 100vw;
  margin-left: calc(50% - 50vw);
  margin-right: calc(50% - 50vw);
  padding-inline: max(2.5rem, calc((100vw - 1240px) / 2));
}
@media (max-width: 700px) {
  .ev-counts-section,
  .ev-gap-section,
  .ev-gov-section,
  .r2s-strip,
  .r2s-schools,
  .r2s-measure { padding-inline: 1.25rem; }
}


/* ── /read-2-succeed full-bleed fix (2026-08-31) ────────────────────────
   The page component's own scoped rules — .r2s-*[data-astro-cid-ej5gdlvu],
   specificity (0,2,0) — set `margin: 0 -2rem`, which OUT-SPECIFIES the
   generic bleed rule above (0,1,0). The sections therefore took `width:100vw`
   from that rule but kept the -2rem margin, landing 148px right of the page
   edge and giving the document 148px of horizontal overflow. The repeated
   class raises specificity to (0,3,0) so this wins regardless of source order.
   Do not "simplify" the duplicate class names away. */
.r2s-strip.r2s-strip.r2s-strip,
.r2s-how.r2s-how.r2s-how,
.r2s-schools.r2s-schools.r2s-schools,
.r2s-measure.r2s-measure.r2s-measure,
.r2s-costs.r2s-costs.r2s-costs,
.r2s-closing.r2s-closing.r2s-closing {
  width: 100vw;
  max-width: 100vw;
  margin-left: calc(50% - 50vw);
  margin-right: calc(50% - 50vw);
}
/* Re-centre the content inside the bands at the same measure as the page.
   .r2s-closing is excluded: it is a two-panel grid that should bleed edge to edge. */
.r2s-strip.r2s-strip.r2s-strip,
.r2s-how.r2s-how.r2s-how,
.r2s-schools.r2s-schools.r2s-schools,
.r2s-measure.r2s-measure.r2s-measure,
.r2s-costs.r2s-costs.r2s-costs {
  padding-inline: max(2.5rem, calc((100vw - 1240px) / 2));
}
@media (max-width: 700px) {
  .r2s-strip.r2s-strip.r2s-strip,
  .r2s-how.r2s-how.r2s-how,
  .r2s-schools.r2s-schools.r2s-schools,
  .r2s-measure.r2s-measure.r2s-measure,
  .r2s-costs.r2s-costs.r2s-costs { padding-inline: 1.25rem; }
}
/* 100vw ignores a classic (non-overlay) scrollbar, so clip any residual sliver.
   `clip` rather than `hidden` so position:sticky keeps working. */
html, body { overflow-x: clip; }
